  <title>Image Preview</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(17, 24, 39, 0.92);
      --panel-strong: #111827;
      --text: #e5e7eb;
      --muted: #9ca3af;
      --line: rgba(255, 255, 255, 0.08);
      --accent: #ef4444;
      --accent-hover: #dc2626;
      --soft: #1f2937;
      --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(59, 130, 246, 0.16), transparent 34%),
        radial-gradient(circle at bottom, rgba(239, 68, 68, 0.16), transparent 28%),
        var(--bg);
      color: var(--text);
      padding: 24px;
    }

    .preview-card {
      width: min(100%, 720px);
      background: linear-gradient(180deg, rgba(17, 24, 39, 0.96), rgba(10, 15, 27, 0.96));
      border: 1px solid var(--line);
      border-radius: 24px;
      box-shadow: var(--shadow);
      padding: 24px;
    }

    .preview-header h1 {
      margin: 0 0 8px;
      font-size: clamp(1.4rem, 2vw, 2rem);
    }

    .preview-header p {
      margin: 0;
      color: var(--muted);
      line-height: 1.5;
    }

    .image-shell {
      margin-top: 20px;
      border-radius: 20px;
      overflow: hidden;
      border: 1px solid var(--line);
      background: #0f172a;
    }

    .image-shell img {
      display: block;
      width: 100%;
      height: auto;
      aspect-ratio: 16 / 10;
      object-fit: cover;
    }

    .actions {
      display: flex;
      justify-content: flex-end;
      margin-top: 16px;
    }

    .trigger,
    .secondary,
    .danger {
      border: 0;
      border-radius: 999px;
      font: inherit;
      font-weight: 600;
      cursor: pointer;
      transition: transform 160ms ease, background-color 160ms ease, box-shadow 160ms ease;
    }

    .trigger {
      padding: 0.85rem 1.15rem;
      color: #fff;
      background: linear-gradient(135deg, #ef4444, #b91c1c);
      box-shadow: 0 12px 28px rgba(239, 68, 68, 0.28);
    }

    .trigger:hover {
      transform: translateY(-1px);
      background: linear-gradient(135deg, #f87171, #dc2626);
    }

    .trigger:focus-visible,
    .secondary:focus-visible,
    .danger:focus-visible,
    .modal-close:focus-visible {
      outline: 2px solid #93c5fd;
      outline-offset: 3px;
    }

    .modal-backdrop {
      position: fixed;
      inset: 0;
      display: none;
      place-items: center;
      background: rgba(2, 6, 23, 0.72);
      backdrop-filter: blur(12px);
      padding: 24px;
    }

    .modal-backdrop.open {
      display: grid;
    }

    .modal {
      width: min(100%, 460px);
      background: linear-gradient(180deg, rgba(17, 24, 39, 0.98), rgba(9, 14, 24, 0.98));
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 24px;
      box-shadow: var(--shadow);
      padding: 24px;
      position: relative;
      transform: translateY(6px);
      animation: pop 180ms ease-out;
    }

    @keyframes pop {
      from { opacity: 0; transform: translateY(18px) scale(0.98); }
      to { opacity: 1; transform: translateY(6px) scale(1); }
    }

    .modal-close {
      position: absolute;
      top: 16px;
      right: 16px;
      width: 36px;
      height: 36px;
      display: grid;
      place-items: center;
      border: 1px solid var(--line);
      border-radius: 50%;
      background: rgba(255, 255, 255, 0.04);
      color: var(--text);
    }

    .modal h2 {
      margin: 0 40px 10px 0;
      font-size: 1.35rem;
    }

    .modal p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .modal-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      margin-top: 24px;
    }

    .secondary {
      padding: 0.82rem 1.1rem;
      color: var(--text);
      background: var(--soft);
      border: 1px solid var(--line);
    }

    .secondary:hover {
      background: #2b3445;
    }

    .danger {
      padding: 0.82rem 1.1rem;
      color: #fff;
      background: linear-gradient(135deg, #f97316, #ef4444);
    }

    .danger:hover {
      background: linear-gradient(135deg, #fb923c, #dc2626);
    }
  </style>
</head>
<body>
  <main class="preview-card">
    <header class="preview-header">
      <h1>Image preview</h1>
      <p>Review the image in your library before deleting it.</p>
    </header>

    <section class="image-shell" aria-label="Image preview">
      <img
        src="https://images.unsplash.com/photo-1518005020951-eccb494ad742?auto=format&fit=crop&w=1200&q=80"
        alt="A dark desk setup with a laptop, camera, and warm ambient lighting"
      />
    </section>

    <div class="actions">
      <button class="trigger" type="button" id="openModal">Delete image</button>
    </div>
  </main>

  <div class="modal-backdrop" id="backdrop" aria-hidden="true">
    <div class="modal" role="dialog" aria-modal="true" aria-labelledby="dialogTitle" aria-describedby="dialogText">
      <button class="modal-close" type="button" id="closeModal" aria-label="Close dialog">✕</button>
      <h2 id="dialogTitle">Delete this image?</h2>
      <p id="dialogText">
        This will remove the image from your library. You can&apos;t undo this action.
      </p>
      <div class="modal-actions">
        <button class="secondary" type="button" id="cancelButton">Cancel</button>
        <button class="danger" type="button" id="confirmButton">Delete</button>
      </div>
    </div>
  </div>

  <script>
    const backdrop = document.getElementById('backdrop');
    const openModal = document.getElementById('openModal');
    const closeModal = document.getElementById('closeModal');
    const cancelButton = document.getElementById('cancelButton');
    const confirmButton = document.getElementById('confirmButton');

    const openDialog = () => {
      backdrop.classList.add('open');
      backdrop.setAttribute('aria-hidden', 'false');
      closeModal.focus();
    };

    const closeDialog = () => {
      backdrop.classList.remove('open');
      backdrop.setAttribute('aria-hidden', 'true');
      openModal.focus();
    };

    openModal.addEventListener('click', openDialog);
    closeModal.addEventListener('click', closeDialog);
    cancelButton.addEventListener('click', closeDialog);

    confirmButton.addEventListener('click', () => {
      closeDialog();
    });

    backdrop.addEventListener('click', (event) => {
      if (event.target === backdrop) {
        closeDialog();
      }
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && backdrop.classList.contains('open')) {
        closeDialog();
      }
    });
  </script>
</body>
</html>
